css:
.cat-accordion{border:1px solid var(--cat-color-stroke-dark);border-radius:var(--cat-size-radius-md);background:var(--cat-semantic-panel-tint);overflow:hidden;font-family:var(--cat-font-family-ui)}
.cat-accordion+.cat-accordion{margin-top:6px}
.cat-accordion summary{display:flex;align-items:center;justify-content:space-between;gap:10px;padding:10px 14px;font:550 var(--cat-font-size-base) var(--cat-font-family-ui);color:var(--cat-color-ink-hi);cursor:pointer;list-style:none;transition:background var(--cat-motion-fast)}
.cat-accordion summary::-webkit-details-marker{display:none}
.cat-accordion summary:hover{background:var(--cat-color-surface-hover)}
.cat-accordion[open] summary{border-bottom:1px solid var(--cat-color-stroke-softer)}
.cat-accordion summary .chev{transition:transform var(--cat-motion-med) var(--cat-motion-ease-out);color:var(--cat-color-ink-faint)}
.cat-accordion[open] summary .chev{transform:rotate(180deg)}
.cat-accordion .body{padding:12px 14px;font-size:var(--cat-font-size-base);color:var(--cat-color-ink-mid);line-height:1.5}
